import { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import type { AdvCampaignRead } from 'entities/Brand';

import styles from './AdvCampaignCardForCatalog.module.scss';

interface IAdvCampaignCardForCatalogProps extends HTMLAttributes<HTMLDivElement> {
	advCampaign: AdvCampaignRead;
}

export const AdvCampaignCardForCatalog: FC<IAdvCampaignCardForCatalogProps> = ({
	className,
	advCampaign,
	...props
}) => {
	return (
		<Flex vertical {...props} className={cn(className, styles.advCampaignCard)}>
			<img className={styles.advCampaignCard__image} src={advCampaign.image} alt={advCampaign.name} />
			<Typography.Paragraph
				className={styles.advCampaignCard__text}
				ellipsis={{
					rows: 3,
				}}>
				{advCampaign.name}
			</Typography.Paragraph>
		</Flex>
	);
};
