import { Dispatch, RefObject, SetStateAction } from 'react';

const checkScrollState = (
	scrollPosition: number,
	scrollSize: number,
	containerSize: number,
	setCanScrollStart: Dispatch<SetStateAction<boolean>>,
	setCanScrollEnd: Dispatch<SetStateAction<boolean>>,
) => {
	if (setCanScrollStart && setCanScrollEnd) {
		if (scrollPosition === 0) {
			setCanScrollStart(false);
			setCanScrollEnd(true);
		} else if (scrollSize <= containerSize + Math.round(scrollPosition)) {
			setCanScrollStart(true);
			setCanScrollEnd(false);
		} else {
			setCanScrollStart(true);
			setCanScrollEnd(true);
		}
	}
};

export const checkHorizontalScrollState = (
	ref: RefObject<HTMLDivElement | null>,
	setCanScrollLeft: Dispatch<SetStateAction<boolean>>,
	setCanScrollRight: Dispatch<SetStateAction<boolean>>,
) => {
	const element = ref.current;
	if (!element) return;

	checkScrollState(element.scrollLeft, element.scrollWidth, element.offsetWidth, setCanScrollLeft, setCanScrollRight);
};
